'use strict';
/* Static game assets are mapped in art.js and served from assets/. */


const ALL_GODS=['THOTH','HORUS','ANUBIS','SOBEK','SEKHMET','ISIS','OSIRIS','HATHOR','PTAH','BASTET','SET','NEPHTHYS','AMUN','KHONSU','MIN','RA','MAAT','NUT','GEB','MUT','NEHEBKAU','KHNUM','NEITH','TAWERET','BES'];
const CARD_BACKS={"THOTH":{"tagline":"Moon, writing and wisdom","description":"The ibis-headed keeper of writing, calculation and sacred knowledge. Thoth helps maintain cosmic order, records divine decisions and appears at the weighing of the heart. He also governs the moon and the measurement of time.","family":"No universally fixed parents or children; closely associated with Ma’at and sometimes paired with her.","places":["Hermopolis"],"symbols":["ibis","baboon","writing palette","moon disc"],"aspects":["Moon","Magic","Afterlife","Knowledge"],"note":"His association with Ma’at does not always imply a consistent marriage tradition.","source":"https://en.wikipedia.org/wiki/Thoth"},"HORUS":{"tagline":"Sky, kingship and the royal heir","description":"The falcon god of the sky and legitimate kingship. As the young Horus in the Osiris myth, he battles his uncle Set to reclaim his father’s throne. Horus of Edfu is also celebrated alongside Hathor.","family":"Son of Isis and Osiris; rival of Set; Horus of Edfu is Hathor’s partner and father of Ihy at Dendera.","places":["Edfu","Nekhen"],"symbols":["falcon","Eye of Horus","double crown"],"aspects":["Royalty","Protection","Conflict"],"note":"For these cards, Horus means the son of Isis and Osiris, with the Edfu cult connection to Hathor—not Horus the Elder of Kom Ombo.","source":"https://en.wikipedia.org/wiki/Horus"},"ANUBIS":{"tagline":"Embalming and guidance through death","description":"The black jackal-headed guardian of cemeteries and mummification. Anubis protects the dead, guides souls and stands beside the scales in the weighing of the heart. His dark colour evokes rebirth as well as death.","family":"Son of Nephthys and Osiris in the chosen tradition; father of Kebechet.","places":["Cynopolis"],"symbols":["jackal","embalming cloth","weighing scales"],"aspects":["Afterlife","Protection"],"note":"Different Egyptian traditions give Anubis different parents. The Osiris–Nephthys tradition is the answer for this game.","source":"https://en.wikipedia.org/wiki/Anubis"},"SOBEK":{"tagline":"Crocodiles, the Nile and strength","description":"The formidable crocodile god of river power, fertility and protection. Sobek could be dangerous, but his strength also defended the king and helped secure life along the Nile. Sacred crocodiles were honoured in his cult.","family":"Called a son of Neith in the Pyramid Texts; no fixed spouse or child among the game cards.","places":["Kom Ombo","Faiyum"],"symbols":["crocodile","Nile water","solar disc"],"aspects":["Fertility","Protection","Conflict"],"note":"Kom Ombo also honoured Horus the Elder, who is not the form of Horus used on this game card.","source":"https://en.wikipedia.org/wiki/Sobek"},"SEKHMET":{"tagline":"War, plague and healing","description":"A fierce lioness goddess who could unleash sickness or avert it. Her priests were linked with medicine, and her power guarded the pharaoh. As an Eye of Ra goddess, she also embodied the scorching force of the sun.","family":"Daughter of Ra in a common tradition; consort of Ptah; mother of Nefertem.","places":["Memphis","Karnak"],"symbols":["lioness","sun disc","uraeus cobra"],"aspects":["Healing","Protection","Solar","Conflict"],"note":"Sekhmet, Hathor and Bastet share overlapping Eye of Ra traditions; some myths treat Sekhmet as Hathor’s fierce form.","source":"https://en.wikipedia.org/wiki/Sekhmet"},"ISIS":{"tagline":"Magic, motherhood and protection","description":"A resourceful magician and protective mother who restores her murdered husband Osiris and shields their son Horus. Isis is also a powerful mourner and guardian of the dead, and her cult spread far beyond Egypt.","family":"Daughter of Geb and Nut; sister and wife of Osiris; mother of Horus; sister of Set and Nephthys.","places":["Philae","Abydos"],"symbols":["throne headdress","wings","tyet knot"],"aspects":["Magic","Afterlife","Healing","Royalty"],"note":"The Osiris family is described using the widely known Heliopolitan tradition.","source":"https://en.wikipedia.org/wiki/Isis"},"OSIRIS":{"tagline":"Resurrection, the dead and renewed life","description":"Once a mythical king, Osiris is slain by his brother Set and restored through Isis’s magic. He becomes ruler of the dead and a symbol of regeneration, from resurrection to the annual return of crops.","family":"Son of Geb and Nut; brother and husband of Isis; brother of Set and Nephthys; father of Horus and, in this game’s chosen tradition, Anubis.","places":["Abydos","Busiris"],"symbols":["green skin","crook and flail","atef crown"],"aspects":["Afterlife","Fertility","Royalty"],"note":"The parentage of Anubis varies by period and source.","source":"https://en.wikipedia.org/wiki/Osiris"},"HATHOR":{"tagline":"Music, love, motherhood and joy","description":"A nurturing cow goddess of music, dancing, love and celebration, but also a powerful solar protector. Her sistrum was shaken in worship. At Dendera she formed a divine family with Horus of Edfu and their child Ihy.","family":"Associated with Ra as daughter or Eye; partner of Horus of Edfu; mother of Ihy in the Dendera tradition.","places":["Dendera","Edfu"],"symbols":["cow horns","sun disc","sistrum"],"aspects":["Fertility","Joy","Solar","Royalty"],"note":"Hathor and Horus meet at Edfu in the Festival of the Beautiful Reunion; traditions about solar kinship vary.","source":"https://en.wikipedia.org/wiki/Hathor"},"PTAH":{"tagline":"Creation through thought and speech","description":"The craftsman creator of Memphis, who brings the world into being through his heart and tongue. Ptah protects makers, builders and artisans. He is shown as a wrapped figure holding a combined ankh, djed and was sceptre.","family":"Self-created in one tradition; consort of Sekhmet; father of Nefertem. Also linked to Bastet in some traditions.","places":["Memphis","Karnak"],"symbols":["blue skullcap","djed pillar","ankh–djed–was sceptre"],"aspects":["Creation","Knowledge","Protection"],"note":"Karnak has a smaller Ptah temple, not just temples for Amun and Khonsu.","source":"https://en.wikipedia.org/wiki/Ptah"},"BASTET":{"tagline":"Cats, households and protective joy","description":"Originally a fierce lioness protector, Bastet later became especially associated with cats, domestic safety and childbirth. She could repel illness and evil spirits, yet also delighted in music and festival celebrations.","family":"Daughter of Ra in some traditions; sometimes linked to Ptah as consort; associated with the lioness goddess Sekhmet.","places":["Bubastis"],"symbols":["cat","sistrum","ointment jar"],"aspects":["Protection","Joy","Solar","Healing"],"note":"Bastet’s gentler cat form and Sekhmet’s lioness form overlap historically, but they remain separate game cards.","source":"https://en.wikipedia.org/wiki/Bastet"},"SET":{"tagline":"Desert storms, rivalry and force","description":"God of deserts, storms and disruption, Set murders his brother Osiris and challenges Horus for Egypt’s throne. Yet he is not merely evil: he can defend Ra’s solar boat against the threatening serpent Apep.","family":"Son of Geb and Nut; brother of Osiris, Isis and Nephthys; consort of Nephthys; opponent of Horus.","places":["Sepermeru","Avaris"],"symbols":["Set animal","was sceptre","desert"],"aspects":["Conflict","Royalty","Protection"],"note":"His relationship to Horus depends on the form of Horus; here he is the uncle and rival of Horus the Younger.","source":"https://en.wikipedia.org/wiki/Set_(deity)"},"NEPHTHYS":{"tagline":"Mourning and protection of the dead","description":"The watchful sister of Isis protects the dead, mourns Osiris and lends magical aid in funerary rites. Her name means “Lady of the House”, and her distinctive headdress combines a house sign and basket.","family":"Daughter of Geb and Nut; sister of Isis, Osiris and Set; consort of Set; mother of Anubis in the chosen tradition.","places":["Sepermeru"],"symbols":["house-and-basket headdress","protective wings"],"aspects":["Afterlife","Magic","Protection"],"note":"Ancient accounts sometimes give Nephthys other partners or children; the card uses her common funerary role.","source":"https://en.wikipedia.org/wiki/Nephthys"},"AMUN":{"tagline":"The hidden god and Theban king","description":"Known as the Hidden One, Amun became the chief divine patron of Thebes and a major god of kingship. Combined with Ra as Amun-Ra, he acquired great solar power. His priests served at vast Karnak temples.","family":"Consort of Mut; father of Khonsu in the Theban Triad. Other creator genealogies vary.","places":["Karnak","Luxor Temple"],"symbols":["tall double plumes","ram","sun disc in Amun-Ra form"],"aspects":["Creation","Royalty","Solar"],"note":"Amun can merge with Min as Amun-Min; this does not make the two characters parent and child.","source":"https://en.wikipedia.org/wiki/Amun"},"KHONSU":{"tagline":"Moonlight, travel and healing","description":"The youthful moon god whose name is often explained as “traveller”. Khonsu measures the passing of nights, guards people journeying after dark and drives away harmful spirits. He was worshipped with his parents at Thebes.","family":"Son of Amun and Mut in the Theban Triad.","places":["Karnak","Thebes"],"symbols":["crescent and moon disc","sidelock of youth","crook and flail"],"aspects":["Moon","Healing","Protection"],"note":"Khonsu and Thoth share lunar associations and can be combined as Khonsu–Thoth in some cults.","source":"https://en.wikipedia.org/wiki/Khonsu"},"MIN":{"tagline":"Fertility, harvest and regeneration","description":"An ancient fertility god worshipped at Coptos and Akhmim. Min was linked to agricultural growth, masculine potency and the king’s vitality. His emblems include the raised flail and prickly lettuce used as an offering.","family":"No single stable genealogy; a hymn calls him a son of Isis and Osiris. Linked with Amun in the combined form Amun-Min.","places":["Coptos","Akhmim"],"symbols":["raised flail","prickly lettuce","double feather crown"],"aspects":["Fertility","Royalty"],"note":"If asked whether he is a child of Osiris, answer YES because that attested hymn is printed here.","source":"https://en.wikipedia.org/wiki/Min_(god)"},"RA":{"tagline":"Sun, kingship and creation","description":"The falcon-headed sun god crosses the sky by day and the underworld by night. Ra is a supreme creator and a model of royal power, and his radiant light sustains life while driving back chaos.","egyptianName":"Rꜥ","family":"Often described as a self-created creator; father or ancestor of many gods in different traditions.","places":["Heliopolis","Abu Ghurab"],"symbols":["sun disc","falcon","solar boat","uraeus cobra"],"aspects":["Solar","Creation","Royalty","Protection"],"note":"Ra often merges with other gods, especially as Amun-Ra and Ra-Horakhty, but this card represents Ra himself.","source":"https://en.wikipedia.org/wiki/Ra"},"MAAT":{"tagline":"Truth, justice and cosmic order","description":"Maat embodies the balance that keeps the universe in harmony. Her feather is weighed against the heart of the dead, and her presence governs truth, justice and right conduct for gods, kings and ordinary people alike.","egyptianName":"Mꜣꜥt","family":"Usually treated as a daughter of Ra and closely associated with Thoth, though she is also a divine principle as much as an individual goddess.","places":["Karnak","Thebes"],"symbols":["ostrich feather","scales","seated goddess"],"aspects":["Justice","Order","Truth","Afterlife"],"note":"Maat is both a goddess and the idea of cosmic order, so ancient texts sometimes speak of her more as a principle than a family-tree figure.","source":"https://en.wikipedia.org/wiki/Maat"},"NUT":{"tagline":"The sky, stars and heavenly protection","description":"Nut is the great sky goddess whose body arches over the earth. She swallows the sun at dusk and gives birth to it again at dawn, and she also protects the dead by welcoming them into the heavens.","egyptianName":"Nwt","family":"Daughter of Shu and Tefnut; sister and wife of Geb; mother of Osiris, Isis, Set and Nephthys.","places":["Heliopolis","Dendera"],"symbols":["stars","sky arch","heavens"],"aspects":["Sky","Protection","Afterlife","Cosmos"],"note":"Nut is usually shown arching over the earth, but this deck keeps the same standing-card format for every deity.","source":"https://en.wikipedia.org/wiki/Nut_(goddess)"},"GEB":{"tagline":"Earth, fertile land and foundations","description":"Geb is the earth god whose body represents the land itself. He is linked with fertility, crops and the rich ground beneath all life, and he also belongs to the royal lineage through his famous divine children.","egyptianName":"Gb","family":"Son of Shu and Tefnut; brother and husband of Nut; father of Osiris, Isis, Set and Nephthys.","places":["Heliopolis"],"symbols":["goose","green skin","earth"],"aspects":["Earth","Fertility","Royalty"],"note":"The goose is a classic emblem of Geb, and his name is often written with a goose sign in hieroglyphs.","source":"https://en.wikipedia.org/wiki/Geb"},"MUT":{"tagline":"Motherhood, queenship and Theban protection","description":"Mut is the great mother goddess of Thebes and an important patron of queenship. Worshipped beside Amun and Khonsu, she formed the Theban Triad and was often shown with royal crowns and vulture imagery.","egyptianName":"Mwt","family":"Consort of Amun; mother of Khonsu in the Theban Triad.","places":["Karnak","Thebes"],"symbols":["vulture headdress","double crown","papyrus sceptre"],"aspects":["Motherhood","Protection","Royalty"],"note":"Mut’s cult was especially strong at Karnak, where she complements Amun and Khonsu as the third member of the Theban Triad.","source":"https://en.wikipedia.org/wiki/Mut"},"NEHEBKAU":{"tagline":"Primordial serpent, protection and the afterlife","description":"Nehebkau is a primordial serpent god who became a protective funerary deity associated with the afterlife. He was believed to aid and empower the dead, to stand among the assessors of Ma’at, and to accompany or protect the solar god on his journey.","egyptianName":"Nḥb-kꜣw","family":"Traditions vary: he is linked with Serket, Geb and Renenutet, and his consort is sometimes given as Nehmetawy.","places":["Heliopolis","Herakleopolis"],"symbols":["serpent","two-headed snake","ankh","protective magic"],"aspects":["Afterlife","Protection","Magic","Judgement"],"note":"Wikipedia describes Nehebkau as a primordial snake god who later gained an important benevolent role in funerary religion.","source":"https://en.wikipedia.org/wiki/Nehebkau"},"KHNUM":{"tagline":"Creation, the Nile and craftsmanship","description":"Khnum is the ram-headed creator god associated with the source of the Nile and with fashioning life on a potter’s wheel. He shapes gods and humans alike and was worshipped as a life-giving divine craftsman.","egyptianName":"ẖnmw","family":"Frequently paired with Neith or Satet in different local traditions; also linked with Anuket and Heka.","places":["Elephantine","Esna"],"symbols":["ram","potter’s wheel","Nile water","clay vessel"],"aspects":["Creation","Craft","Fertility","Nile"],"note":"Wikipedia emphasizes Khnum’s role as a creator who molds bodies on the potter’s wheel and as a god of the Nile’s life-giving waters.","source":"https://en.wikipedia.org/wiki/Khnum"},"NEITH":{"tagline":"War, weaving and primordial motherhood","description":"Neith is one of Egypt’s most ancient goddesses, associated with warfare, weaving and motherhood. She could appear as a creator figure, and her symbolism joins martial power with protective and maternal authority.","egyptianName":"Nt","family":"Often described as self-created; different traditions name gods such as Sobek or Ra among her children.","places":["Sais","Esna"],"symbols":["crossed arrows","shield or sheath","red crown","loom"],"aspects":["War","Creation","Motherhood","Craft"],"note":"I interpreted your “Neither” request as Neith, the goddess previously suggested for the roster.","source":"https://en.wikipedia.org/wiki/Neith"},"TAWERET":{"tagline":"Childbirth, fertility and household protection","description":"Taweret is the protective goddess of childbirth and fertility. Usually shown with the body of a hippopotamus and the features of other protective animals, she guarded mothers, babies and the household against danger.","egyptianName":"Tꜣ-wrt","family":"Often linked with protective household deities and sometimes paired with Bes in later tradition.","places":["Household worship throughout Egypt"],"symbols":["hippopotamus","sa-sign","crocodile tail","ivory wand"],"aspects":["Protection","Childbirth","Fertility","Household"],"note":"Wikipedia notes that Taweret was not tied to one great state temple so much as to broad household devotion across Egypt.","source":"https://en.wikipedia.org/wiki/Taweret"},"BES":{"tagline":"Household joy, childbirth and protection","description":"Bes is a protective household deity especially associated with mothers, children, childbirth, music and festivity. His fearsome comic face and noisy revelry were thought to drive away harmful forces.","egyptianName":"Bs","family":"Sometimes paired with Taweret or Beset in later traditions; his mythology is less fixed than that of many state gods.","places":["Hermopolis","Household worship throughout Egypt"],"symbols":["feathered crown","tambourine","protective knife","lion features"],"aspects":["Protection","Childbirth","Music","Household"],"note":"Wikipedia describes Bes as a popular guardian of the home whose worship spread widely beyond any single temple center.","source":"https://en.wikipedia.org/wiki/Bes"}};
const DEFAULT_NAMES=['Charlie','Mark','James','Pete','Robert','Sarah','Harry'];
const ALL_PLAYERS=[1,2,3,4,5,6,7];
const ACTIVE_KEY='findgod-active-v4';
const LEGACY_ACTIVE_KEYS=['findgod-active-v3','findgod-active-v2'];
const STATE_PREFIX='findgod-board-v5|';
const NAMES_KEY='findgod-names-v2';
const SCORE_KEY='findgod-scores-v1|';
const MIN_GOD_COUNT=7;
const MAX_GOD_COUNT=ALL_GODS.length;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
function getStore(k){try{return localStorage.getItem(k)}catch(e){return null}}
function putStore(k,v){try{localStorage.setItem(k,v)}catch(e){}}
function delStore(k){try{localStorage.removeItem(k)}catch(e){}}
function jsonStore(k,fallback){try{let v=getStore(k);return v==null?fallback:(JSON.parse(v)??fallback)}catch(e){return fallback}}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function seededRng(seed){let x=hash(seed);return function(){x=(x+0x6D2B79F5)>>>0;let t=x;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296}}
function canonical(s){return String(s||'').trim().replace(/\s+/g,' ').toUpperCase()}
function validRound(n){let x=Number(n);return Number.isInteger(x)&&x>=1&&x<=9999}
function validGodCount(n){let x=Number(n);return Number.isInteger(x)&&x>=MIN_GOD_COUNT&&x<=MAX_GOD_COUNT}
function shuffleAll(seed,round){let a=ALL_GODS.slice(),rand=seededRng('FIND-THE-GOD-v2|'+canonical(seed)+'|ROUND:'+round);for(let i=a.length-1;i>0;i--){let j=Math.floor(rand()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function visibleGods(seed,round,godCount){return shuffleAll(seed,round).slice(0,Number(godCount))}
function normalRoster(r){return Array.isArray(r)&&r.length>=2&&r.length<=7&&r.every(x=>Number.isInteger(x)&&x>=1&&x<=7)&&new Set(r).size===r.length?r.slice().sort((a,b)=>a-b):ALL_PLAYERS.slice()}
function assignmentMap(seed,round,roster,godCount){let cards=visibleGods(seed,round,godCount), map={}; normalRoster(roster).forEach((p,i)=>map[p]=cards[i]); return map}
function dealCode(seed,round,roster,godCount){let r=normalRoster(roster);return (hash('CHECK-v4|'+canonical(seed)+'|ROUND:'+round+'|PLAYERS:'+r.join(',')+'|GODS:'+godCount)%65536).toString(16).toUpperCase().padStart(4,'0')}
function scoreKey(seed,roster){let r=normalRoster(roster);return SCORE_KEY+canonical(seed)+'|'+r.join(',')}
function blankScores(roster){let s={}; for(const p of normalRoster(roster)) s[p]=0; return s}
function loadScores(seed,roster){let base=blankScores(roster), saved=jsonStore(scoreKey(seed,roster),{}); for(const p of Object.keys(base)) if(Number.isFinite(Number(saved[p]))) base[p]=Number(saved[p]); return base}
function saveScores(seed,roster,scores){putStore(scoreKey(seed,roster), JSON.stringify(scores))}
function resetScores(seed,roster){delStore(scoreKey(seed,roster));}
function playerName(n){let v=names[String(n)];return (typeof v==='string'&&v.trim())||DEFAULT_NAMES[n-1]}
function turnOrder(round,roster){let r=normalRoster(roster); if(!r.length) return []; let start=(Number(round)-1)%r.length; return r.slice(start).concat(r.slice(0,start));}
function turnOrderNames(round,roster){return turnOrder(round,roster).map(n=>playerName(n)).join(' → ')}
function startName(round,roster){let ord=turnOrder(round,roster); return ord.length?playerName(ord[0]):'—'}
function playerPosition(round,roster,player){let ord=turnOrder(round,roster); let idx=ord.indexOf(player); return idx<0?null:idx+1}
let names=jsonStore(NAMES_KEY,{}), active=jsonStore(ACTIVE_KEY,null);
if(!active){for(const k of LEGACY_ACTIVE_KEYS){active=jsonStore(k,null); if(active) break;}}
if(active){active.roster=normalRoster(active.roster); active.godCount=validGodCount(active.godCount)?Number(active.godCount):7; if(!active.seed||!validRound(active.round)||!Number.isInteger(active.player)||!active.roster.includes(active.player)) active=null}
let page=active?'game':'setup', selected=null, modal=null, board={excluded:{},confirmed:{}}, scores=active?loadScores(active.seed,active.roster):{};
let setupSelection=new Set(active?.roster||ALL_PLAYERS);
let setupGodCount=active?.godCount||7;
let setupDraft={seed:active?.seed||'',round:active?.round||1,player:active?.player||chosen()[0]};
function chosen(){return ALL_PLAYERS.filter(n=>setupSelection.has(n))}
function inPlayGods(){return visibleGods(active.seed,active.round,active.godCount)}
function deductionGods(){return inPlayGods().filter(g=>g!==myGod())}
function otherPlayers(){return active.roster.filter(n=>n!==active.player)}
function myGod(){return assignmentMap(active.seed,active.round,active.roster,active.godCount)[active.player]}
function boardSuffix(){return canonical(active.seed)+'|'+active.round+'|'+active.roster.join(',')+'|'+active.player+'|'+active.godCount}
function boardKey(){return STATE_PREFIX+boardSuffix()}
function loadBoard(){
 let saved=jsonStore(boardKey(),null); board={excluded:{},confirmed:{}}; let gods=inPlayGods();
 if(saved){for(let p of otherPlayers()){
   let exclusions=saved.excluded?.[p]; if(Array.isArray(exclusions)) board.excluded[p]=[...new Set(exclusions)].filter(g=>gods.includes(g)&&g!==myGod());
   let conf=saved.confirmed?.[p]; if(gods.includes(conf)&&conf!==myGod()&&!Object.values(board.confirmed).includes(conf)) board.confirmed[p]=conf;
 }}
}
if(active){loadBoard(); selected=otherPlayers()[0]}
function persistBoard(){if(active) putStore(boardKey(),JSON.stringify(board))}
function persistScores(){if(active) saveScores(active.seed,active.roster,scores)}
function img(g){return ART[g]}
// Cache each round's card illustrations after the visible cards start loading.
const warmedImages=new Set();
let imageWarmTimer=null;
function warmRoundImages(){
 if(!active)return;
 clearTimeout(imageWarmTimer);
 const pending=inPlayGods().filter(g=>!warmedImages.has(g));
 imageWarmTimer=setTimeout(()=>{
  let i=0;
  function next(){
   if(i>=pending.length)return;
   const god=pending[i++];
   warmedImages.add(god);
   const image=new Image();
   image.onload=image.onerror=next;
   image.src=img(god);
   if(image.complete)next();
  }
  next();
 },800);
}
function manualRuled(p,g){return (board.excluded[p]||[]).includes(g)}
function autoReason(p,g){if(g===myGod()) return 'your own god'; if(board.confirmed[p]&&board.confirmed[p]!==g) return playerName(p)+' is confirmed as '+board.confirmed[p]; for(let i of otherPlayers()) if(i!==p&&board.confirmed[i]===g) return playerName(i)+' is confirmed as '+g; return ''}
function cardStatus(p,g){if(board.confirmed[p]===g) return 'yes'; if(manualRuled(p,g)||autoReason(p,g)) return 'no'; return 'possible'}
function possibilities(p){return deductionGods().filter(g=>cardStatus(p,g)!=='no').length}
function confirmedCount(){return otherPlayers().filter(p=>board.confirmed[p]).length}
function toast(s){let old=$('#toast'); if(old) old.remove(); let d=document.createElement('div'); d.id='toast'; d.className='toast'; d.textContent=s; document.body.appendChild(d); clearTimeout(toast.timer); toast.timer=setTimeout(()=>d.remove(),2400)}
function header(){return `<div class="head"><div class="logo"><div class="sigil">𓂀</div><div><div class="brand">FIND THE GOD</div><div class="minor">The Divine Disguise</div></div></div></div>`}
function rosterControls(){return ALL_PLAYERS.map(n=>`<label class="rosterChoice"><input type="checkbox" data-roster="${n}" ${setupSelection.has(n)?'checked':''}><span class="pill">#${n}</span><span>${esc(playerName(n))}</span></label>`).join('')}
function playerOptions(selectedId){return chosen().map(n=>`<option value="${n}" ${selectedId===n?'selected':''}>${esc(playerName(n))} (#${n})</option>`).join('')}
function godCountOptions(sel){let out=''; for(let n=MIN_GOD_COUNT;n<=MAX_GOD_COUNT;n++) out += `<option value="${n}" ${Number(sel)===n?'selected':''}>${n}</option>`; return out;}
function selectedGodCount(){return Number($('#godCount')?.value||setupGodCount||7)}
function decoyCount(count,rosterCount){return Math.max(0, Number(count)-Number(rosterCount))}
function suffix(n){return n===1?'st':n===2?'nd':n===3?'rd':'th'}
function scoreRows(roster,scr){return normalRoster(roster).sort((a,b)=>(scr[b]||0)-(scr[a]||0)||a-b).map(p=>`<div class="summaryRows"><span>${esc(playerName(p))}</span><strong>${scr[p]||0}</strong></div>`).join('')}
function rules(){let r=page==='setup'?chosen():active.roster, round=Number($('#round')?.value)||active?.round||1, godCount=page==='setup'?selectedGodCount():active.godCount; return `<ol class="helpList"><li>Look at your secret god; don't show anyone. Everyone draws from the same ${godCount} god cards, but your own god is hidden on your deduction boards.</li><li>Take turns in this order: <strong>${esc(turnOrderNames(round,r))}</strong>.</li><li>Ask any player a yes/no question about their god's appearance. A <strong>yes</strong> lets you ask again; a <strong>no</strong> ends your turn.</li><li>You may accuse aloud: “Sarah, are you Isis?” Yes lets you continue; no ends your turn.</li><li>In your private Guess Who board, use <strong>✓</strong> for a confirmed god and <strong>✕</strong> to rule one out. Tap again to undo.</li><li>Any enlarged god card can be flipped to read mythology and relationships. The printed facts are the official answers for this game.</li><li>The first player to correctly identify all ${r.length-1} other ${r.length===2?'god':'gods'} wins. Any extra cards are decoys.</li></ol>`}

/* Shareable setup links/codes carry only public game configuration, never secret gods or deductions. */
function rememberSetupInputs(){
 if(page!=='setup') return;
 let seed=$('#seed'), round=$('#round'), player=$('#player');
 if(seed) setupDraft.seed=seed.value;
 if(round) setupDraft.round=round.value;
 if(player) setupDraft.player=Number(player.value);
}
function currentSetupPayload(){
 rememberSetupInputs();
 let seed=canonical(setupDraft.seed), round=Number(setupDraft.round), roster=chosen(), count=selectedGodCount();
 if(!seed||seed.length>32){showSetupError('Enter a seed of 1–32 characters before sharing.');return null}
 if(!validRound(round)){showSetupError('Choose a round from 1 to 9999.');return null}
 if(!validGodCount(count)){showSetupError('Choose a valid number of god cards.');return null}
 if(roster.length<2){showSetupError('Choose at least two players.');return null}
 return {v:1,s:seed,r:round,g:count,p:roster,n:ALL_PLAYERS.map(p=>playerName(p))};
}
function encodeSetupCode(payload){
 let binary='',bytes=new TextEncoder().encode(JSON.stringify(payload));
 for(let b of bytes) binary+=String.fromCharCode(b);
 return 'FTG1.'+btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
function decodeSetupCode(value){
 let code=String(value||'').trim();
 let tag=code.indexOf('#ftg=');
 if(tag!==-1) code=code.slice(tag+5).split('&')[0];
 else if(code.startsWith('ftg=')) code=code.slice(4);
 if(!/^FTG1\.[A-Za-z0-9_-]{8,5000}$/.test(code)) throw new Error('Unrecognised setup code.');
 let s=code.slice(5).replace(/-/g,'+').replace(/_/g,'/');
 s+='='.repeat((4-s.length%4)%4);
 let bytes=Uint8Array.from(atob(s), c=>c.charCodeAt(0));
 let obj=JSON.parse(new TextDecoder().decode(bytes));
 if(!obj||obj.v!==1||typeof obj.s!=='string'||!canonical(obj.s)||canonical(obj.s).length>32||
   !validRound(obj.r)||!validGodCount(obj.g)||!Array.isArray(obj.p)||obj.p.length<2||obj.p.length>7||
   obj.p.some(x=>!Number.isInteger(x)||x<1||x>7)||new Set(obj.p).size!==obj.p.length||
   !Array.isArray(obj.n)||obj.n.length!==7||obj.n.some(n=>typeof n!=='string'||!n.trim()||n.length>26)){
   throw new Error('The shared game settings are invalid or from an unsupported version.');
 }
 return {s:canonical(obj.s),r:Number(obj.r),g:Number(obj.g),p:normalRoster(obj.p),n:obj.n.map(n=>n.trim())};
}
function loadSharedSetup(config){
 names=Object.fromEntries(ALL_PLAYERS.map((p,i)=>[String(p),config.n[i]]));
 putStore(NAMES_KEY,JSON.stringify(names));
 setupSelection=new Set(config.p);
 setupGodCount=config.g;
 setupDraft={seed:config.s,round:config.r,player:config.p[0]};
 page='setup'; selected=null; modal=null;
}
function shareSetup(config=currentSetupPayload()){
 if(!config) return;
 let code=encodeSetupCode(config);
 let hosted=window.location.protocol==='https:'||window.location.protocol==='http:';
 let result;
 if(hosted){let url=new URL(window.location.href);url.hash='ftg='+code;result=url.href}
 else result=code;
 let msg=hosted?'Setup link copied. Each player selects their own name.':'Setup code copied. Send the HTML plus this code; players use Paste setup code.';
 if(navigator.clipboard?.writeText){
   navigator.clipboard.writeText(result).then(()=>toast(msg)).catch(()=>{prompt('Copy this '+(hosted?'game link':'setup code')+':',result)});
 } else prompt('Copy this '+(hosted?'game link':'setup code')+':',result);
}
function activeSetupPayload(){return {v:1,s:active.seed,r:active.round,g:active.godCount,p:active.roster,n:ALL_PLAYERS.map(p=>playerName(p))}}
function importSetup(){
 let value=prompt('Paste a shared setup code or full setup link:','');
 if(value===null||!value.trim()) return;
 try{let config=decodeSetupCode(value);loadSharedSetup(config);draw(false);toast('Shared setup loaded. Choose your own name.');}
 catch(e){showSetupError(e.message||'Invalid setup code.');}
}

function setupSummaryText(){let roster=chosen(), gc=selectedGodCount(), d=decoyCount(gc,roster.length); return `${roster.length} players will receive gods. ${d===0?'No decoy cards this round.':d+' decoy '+(d===1?'card remains':'cards remain')+' visible.'}`}
function setupPage(){let s=setupDraft.seed, r=setupDraft.round, p=setupDraft.player, gc=setupGodCount; let liveScores=(active&&canonical(active.seed)===canonical(s)&&JSON.stringify(active.roster)===JSON.stringify(chosen()))?scores:loadScores(s,chosen()); return `${header()}<div class="kicker">A mystery of Egyptian gods</div><h1 class="h1">Set up your game</h1><p class="sub">Everyone enters the same game seed, round, player list, and number of god cards. Then choose your own name to receive a secret god. You can also share these settings as a link or code.</p>
<section class="panel"><h2 class="panelTitle">Join your game</h2><form id="setupForm"><div class="formGrid"><label class="full"><span class="label">Shared game seed</span><input class="field" id="seed" autocapitalize="characters" autocorrect="off" spellcheck="false" maxlength="32" placeholder="e.g. NILE42" value="${esc(s)}" required></label><label><span class="label">Round</span><input class="field" id="round" inputmode="numeric" type="number" min="1" max="9999" value="${r}" required></label><label><span class="label">Your name</span><select class="field" id="player">${playerOptions(chosen().includes(p)?p:chosen()[0])}</select></label><label><span class="label">God cards in play</span><select class="field" id="godCount">${godCountOptions(gc)}</select></label></div><div class="divider"></div>
<div class="row space" style="margin-bottom:8px"><span class="label" style="margin:0">Who's playing?</span><span class="pill" id="activeCount">${chosen().length} of 7 playing</span></div><p class="helper">Tap to exclude anyone who isn't playing. Every phone should use the same group of players.</p><div class="rosterChoices" id="rosterControls">${rosterControls()}</div><p class="helper" id="rosterNote">${setupSummaryText()}</p><p class="helper" id="startLabel"><strong>Starting player:</strong> ${esc(startName(r,chosen()))}</p><p class="helper" id="turnLabel"><strong>Turn order:</strong> ${esc(turnOrderNames(r,chosen()))}</p><button class="btn full" type="submit">${active?'Continue game':'Start playing'} →</button></form><div class="row" style="margin-top:10px"><button class="btn low" data-act="random-seed" style="flex:1">🎲 Suggest seed</button><button class="btn low" data-act="copy-invite" style="flex:1">↗ Copy details</button></div><div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn alt" data-act="share-setup" style="flex:1;min-width:138px">🔗 Share setup</button><button class="btn low" data-act="paste-setup" style="flex:1;min-width:138px">📋 Paste setup code</button></div><p class="helper" style="margin:8px 0 0">Hosted HTML: share a clickable link. Downloaded offline HTML: share the file and a setup code. Each person selects their own name.</p><div id="setupError" class="warning" style="display:none;margin-top:12px"></div></section>
<section class="panel quiet"><div class="row space" style="margin-bottom:8px"><h2 class="panelTitle" style="margin:0">Scoreboard</h2><button class="btn low" data-act="reset-scores">Reset scores</button></div><div id="setupScores">${scoreRows(chosen(),liveScores)}</div><p class="helper">Scores are tracked per seed and player group.</p></section>
<section class="panel quiet"><h2 class="panelTitle">Your player names</h2><p class="helper">Charlie, Mark, James, Pete, Robert, Sarah and Harry are preloaded. You can edit them below. Make the same changes on each phone.</p><details><summary>Edit the names</summary><div class="roster" style="margin-top:12px">${ALL_PLAYERS.map(i=>`<label class="nameRow"><span class="number">#${i}</span><input class="field" data-name="${i}" maxlength="26" value="${esc(playerName(i))}"></label>`).join('')}</div></details></section>
<section class="panel quiet"><h2 class="panelTitle">How to play</h2><div id="setupRules">${rules()}</div><p class="helper">All questions, answers and accusations happen aloud. Your phone only deals your god and remembers your deductions.</p></section><div class="foot">Find the God · ${MAX_GOD_COUNT} gods available</div>`}
function gameTop(){return `<div class="gameTop"><div class="toolbar"><div class="toolbarTitle"><div class="brand">FIND THE GOD</div><div class="minor">${esc(playerName(active.player))} · Round ${active.round}</div></div><button class="iconBtn" data-act="share-active" aria-label="Share this game round" title="Share game">↗ Share</button><button class="iconBtn" data-act="goto-setup" aria-label="Game settings">⚙</button></div><div class="gameMeta"><span class="pill">${confirmedCount()} / ${otherPlayers().length} confirmed</span><span class="pill">${active.godCount} cards</span><span class="pill">Deal code ${esc(dealCode(active.seed,active.round,active.roster,active.godCount))}</span></div></div>`}
function playerTile(p){
 let position=playerPosition(active.round,active.roster,p), wins=Number(scores[p]||0), own=p===active.player;
 let is=!own&&selected===p, conf=!own?board.confirmed[p]:null, left=!own?possibilities(p):0;
 let status=own?'YOU':conf?'✓ '+conf:left+' possible';
 let name=esc(playerName(p));
 let inner=`<span class="playerTop"><span class="playerIdentity"><span class="turnBadge" title="Turn ${position}" aria-label="Turn ${position}">${position}</span><span class="who">${name}</span></span><span class="scoreTag" title="${wins} round ${wins===1?'win':'wins'}" aria-label="${wins} round ${wins===1?'win':'wins'}"><span aria-hidden="true">🏆</span><span class="scoreCount">${wins}</span></span></span><span class="whoStatus ${conf?'solved':''} ${own?'self':''}">${status}</span>`;
 if(own) return `<button type="button" class="playerButton isSelf" data-act="my-god" aria-label="You: ${name}, turn ${position}, ${wins} ${wins===1?'win':'wins'}. Tap to reveal your secret god" title="Tap to peek at your god">${inner}</button>`;
 return `<button type="button" class="playerButton ${is?'active':''}" data-act="select-player" data-player="${p}" aria-pressed="${is}" aria-label="Turn ${position}, ${name}, ${wins} ${wins===1?'win':'wins'}, ${conf?'confirmed as '+conf:left+' possible gods'}">${inner}</button>`;
}
function godTile(p,g){let state=cardStatus(p,g), why=autoReason(p,g), manual=manualRuled(p,g); let stateNote=state==='yes'?'Confirmed':state==='no'?(why&&!manual?'Ruled out automatically':'Ruled out'):''; return `<div class="godCard ${state==='yes'?'isConfirmed':state==='no'?'isRuled':''}" data-tile="${g}">
 <div class="portraitWrap"><img src="${img(g)}" loading="${deductionGods().indexOf(g)<4?'eager':'lazy'}" ${deductionGods().indexOf(g)<4?'fetchpriority="high"':''} decoding="async" width="320" height="480" alt="${g}, Egyptian deity" draggable="false">${state==='yes'?'<div class="portraitShade confirmed"><span class="bigMark">✓</span></div>':state==='no'?'<div class="portraitShade ruled"><span class="bigMark">✕</span></div>':''}${stateNote?`<div class="stateMini ${state==='yes'?'yes':'no'}">${state==='yes'?'CONFIRMED':why&&!manual?'AUTO RULED OUT':'RULED OUT'}</div>`:''}</div>
 <div class="godCaption">${g}</div>
 <div class="cardActions"><button class="markBtn ${state==='yes'?'onYes':''}" data-act="tick" data-player="${p}" data-god="${g}" aria-pressed="${state==='yes'}" aria-label="${state==='yes'?'Undo confirmation':'Confirm'} ${esc(g)} for ${esc(playerName(p))}" title="Confirm / undo">✓</button>
 <button class="markBtn ${state==='no'?'onNo':''}" data-act="cross" data-player="${p}" data-god="${g}" aria-pressed="${state==='no'}" aria-label="${state==='no'?'Undo rule out':'Rule out'} ${esc(g)} for ${esc(playerName(p))}" title="Rule out / undo">✕</button>
 <button class="markBtn zoom" data-act="view" data-god="${g}" aria-label="Enlarge ${g}" title="Enlarge">⌕</button></div></div>`}
function gamePage(){if(!otherPlayers().includes(selected)) selected=otherPlayers()[0]; let p=selected; let number=possibilities(p); let gods=deductionGods(); return `${gameTop()}<section><h2 class="sectionTitle">Who is everyone?</h2><p class="sectionHelp">Turn numbers show play order · 🏆 shows round wins. Tap someone to see your deductions, or tap YOU to peek at your secret god.</p><div class="playerGrid">${turnOrder(active.round,active.roster).map(playerTile).join('')}</div></section>
<section><div class="browseHeader"><div><h2 class="sectionTitle">${esc(playerName(p))}'s gods</h2><div class="hint">Tap ✓ confirm · ✕ rule out · ⌕ enlarge & flip</div></div><span class="pill">${board.confirmed[p]?'✓ Confirmed':number+' possible'}</span></div><div class="godGrid">${gods.map(g=>godTile(p,g)).join('')}</div><div class="legend"><span><b class="y">✓</b> Confirm</span><span><b class="n">✕</b> Rule out</span><span><b class="z">⌕</b> Enlarge</span></div><p class="helper">Your own god is hidden from these boards. Tap ✓ or ✕ again to undo; confirmed gods are ruled out for other players.</p></section>
<div class="bottomPanel"><div class="row space"><div><div class="smallcaps">Your deductions</div><div style="margin-top:3px;font-size:19px;font-weight:800;color:#fce1a5">${confirmedCount()} of ${otherPlayers().length} confirmed</div></div><button class="btn alt" data-act="recap">My matches</button></div>${confirmedCount()===otherPlayers().length?'<div class="notice">🎉 All your gods are marked! Announce the full set aloud and have everyone confirm.</div>':''}<div class="divider"></div><div class="row" style="align-items:stretch;flex-wrap:wrap"><button class="btn low" style="flex:1" data-act="reset-notes">↺ Clear notes</button><button class="btn" style="flex:1" data-act="next-round">Next round →</button></div><p class="helper">When you start the next round, you can record the winner and update the scoreboard.</p></div>`}
function draw(restoreScroll=true){let y=restoreScroll?window.scrollY:0; $('#app').innerHTML=`<main class="container">${page==='setup'?setupPage():gamePage()}</main>`; drawModal(); if(page==='game') warmRoundImages(); if(restoreScroll) window.scrollTo(0,y)}
function backField(label,content,wide=false){
 const value=Array.isArray(content)?content.join(' · '):content;
 return `<div class="backField ${wide?'wide':''}"><b>${esc(label)}</b><span>${esc(value)}</span></div>`;
}
function backContent(g){
 const c=CARD_BACKS[g]; if(!c) return '<p>Card information unavailable.</p>';
 const src=typeof c.source==='string'&&c.source.startsWith('https://en.wikipedia.org/wiki/')?`<p class="backSource"><a href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">Wikipedia reference ↗</a></p>`:'';
 const nameField=c.egyptianName?backField('Egyptian name (translit.)',c.egyptianName):'';
 return `<div class="cardBack" aria-label="Mythology and facts for ${esc(g)}"><div class="backEyebrow">FIND THE GOD · DIVINE LORE</div><h2>${esc(g)}</h2><div class="backTag">${esc(c.tagline)}</div><p class="backDescription">${esc(c.description)}</p><div class="backGrid">${nameField}${backField('Family & relationships',c.family,true)}${backField('Temples & cult centres',c.places)}${backField('Symbols',c.symbols)}${backField('Domains',c.aspects,true)}</div>${c.note?`<p class="backNote"><strong>Tradition note:</strong> ${esc(c.note)}</p>`:''}${src}<div class="backFooter">THE DIVINE DISGUISE · EGYPTIAN MYTHOLOGY</div></div>`;
}
function drawModal(){let el=$('#popup'); if(!modal){el.innerHTML=''; document.body.style.overflow=''; return}
 let body='';
 if(modal.type==='card'){
  const back=modal.side==='back';
  body=`<div class="modalHead"><span class="title">${modal.own?'Your secret god':'Look closer: '+modal.god}</span><button class="iconBtn" data-act="close">✕ Close</button></div>${modal.own?'<p class="helper" style="margin:0 0 10px">Keep this card hidden from everyone else.</p>':''}${back?backContent(modal.god):`<img src="${img(modal.god)}" alt="Full-size ${modal.god} card"><div class="center" style="font-family:Georgia,serif;font-size:22px;color:var(--gold);margin-top:8px">${modal.god}</div>`}<div class="cardFlipBar"><button type="button" class="btn alt" data-act="flip-card" aria-label="${back?'Show illustration':'Show mythology facts'}">${back?'↶ Show front':'↷ Flip for facts'}</button></div>`;
 }
 if(modal.type==='recap') body=`<div class="modalHead"><span class="title">My matches</span><button class="iconBtn" data-act="close">✕ Close</button></div><p class="helper">Read these aloud when you think you have all the gods.</p>${otherPlayers().map(p=>`<div class="summaryRows"><span>${esc(playerName(p))}</span><strong>${esc(board.confirmed[p]||'Not confirmed')}</strong></div>`).join('')}<p class="helper">The other players confirm your answers aloud.</p>`;
 if(modal.type==='winner') body=`<div class="modalHead"><span class="title">Who won round ${active.round}?</span><button class="iconBtn" data-act="close" aria-label="Cancel choosing a winner">✕ Close</button></div><p class="helper">Tap the winner to add one point and begin round ${active.round+1}.</p><div class="winnerGrid">${active.roster.map(p=>`<button type="button" class="winnerChoice" data-act="winner-choice" data-winner="${p}"><span class="winnerName">${esc(playerName(p))}</span><span class="winnerScore">🏆 ${Number(scores[p]||0)} wins</span></button>`).join('')}</div><button class="btn low full" style="margin-top:12px" data-act="winner-choice" data-winner="0">Skip winner · Next round →</button>`;
 if(modal.type==='scores') body=`<div class="modalHead"><span class="title">Scoreboard</span><button class="iconBtn" data-act="close">✕ Close</button></div>${scoreRows(active.roster,scores)}<p class="helper">Scores are tracked for this seed and player group.</p>`;
 el.innerHTML=`<div class="overlay" data-act="close-bg"><div role="dialog" aria-modal="true" aria-label="${modal.type==='card'?'God card':modal.type==='scores'?'Scoreboard':modal.type==='winner'?'Choose the winner':'My matches'}" class="modal">${body}</div></div>`; document.body.style.overflow='hidden';
}
function openCard(g,own=false){modal={type:'card',god:g,own,side:'front'}; drawModal()}
function showSetupError(msg){let e=$('#setupError'); if(e){e.style.display='block'; e.textContent=msg}}
function refreshSetupContent(){let el=$('#setupScores');if(el){let seed=$('#seed')?.value||setupDraft.seed;el.innerHTML=scoreRows(chosen(),loadScores(seed,chosen()))}let rulesEl=$('#setupRules');if(rulesEl)rulesEl.innerHTML=rules()}
function updateSetupRoster(){let was=Number($('#player')?.value)||active?.player||1, list=chosen(); let count=$('#activeCount'); if(count) count.textContent=list.length+' of 7 playing'; let controls=$('#rosterControls'); if(controls) controls.innerHTML=rosterControls(); let sel=$('#player'); if(sel) sel.innerHTML=playerOptions(list.includes(was)?was:list[0]); let note=$('#rosterNote'); if(note) note.textContent=setupSummaryText(); let first=$('#startLabel'); if(first) first.innerHTML='<strong>Starting player:</strong> '+esc(startName(Number($('#round')?.value)||1,list)); let turn=$('#turnLabel'); if(turn) turn.innerHTML='<strong>Turn order:</strong> '+esc(turnOrderNames(Number($('#round')?.value)||1,list)); }
function startGame(seed,round,player,roster,godCount){active={seed:canonical(seed), round:Number(round), player:Number(player), roster:normalRoster(roster), godCount:Number(godCount)}; setupSelection=new Set(active.roster); setupGodCount=active.godCount;setupDraft={seed:active.seed,round:active.round,player:active.player}; scores=loadScores(active.seed,active.roster); putStore(ACTIVE_KEY,JSON.stringify(active)); loadBoard(); selected=otherPlayers()[0]; modal=null; page='game'; window.scrollTo(0,0); draw(false)}
function toggleTick(p,g){if(g===myGod()){toast('That is your own god!'); return} if(board.confirmed[p]===g){delete board.confirmed[p]} else {for(let q of otherPlayers()) if(q!==p&&board.confirmed[q]===g) delete board.confirmed[q]; board.confirmed[p]=g; board.excluded[p]=(board.excluded[p]||[]).filter(x=>x!==g)} persistBoard(); draw()}
function toggleCross(p,g){let auto=autoReason(p,g), list=board.excluded[p]||[]; if(board.confirmed[p]===g){delete board.confirmed[p]; board.excluded[p]=[...new Set([...list,g])]} else if(list.includes(g)){board.excluded[p]=list.filter(x=>x!==g)} else if(auto){toast('Already ruled out: '+auto); return} else {board.excluded[p]=[...list,g]} persistBoard(); draw()}
function handleClick(e){let el=e.target.closest('[data-act]'); if(!el) return; let action=el.dataset.act; if(action==='close-bg'&&e.target!==el) return;
 if(action==='goto-setup'){setupDraft={seed:active?.seed||'',round:active?.round||1,player:active?.player||chosen()[0]};page='setup'; modal=null; window.scrollTo(0,0); draw(false); return}
 if(action==='random-seed'){let v=$('#seed'); if(v){v.value='NILE-'+Math.floor(Math.random()*9000+1000);setupDraft.seed=v.value} return}
 if(action==='share-setup'){shareSetup();return}
 if(action==='share-active'){shareSetup(activeSetupPayload());return}
 if(action==='paste-setup'){importSetup();return}
 if(action==='copy-invite'){let seed=$('#seed')?.value?.trim()||'NILE42', round=$('#round')?.value||'1', r=chosen(), gc=selectedGodCount(); let txt=`Find the God — seed: ${canonical(seed)} | round: ${round} | cards: ${gc} | players: ${r.map(n=>playerName(n)+' (#'+n+')').join(', ')} | deal code: ${dealCode(seed,round,r,gc)}. Choose your own name.`; if(navigator.clipboard?.writeText){navigator.clipboard.writeText(txt).then(()=>toast('Game details copied')).catch(()=>showSetupError(txt))} else showSetupError(txt); return}
 if(action==='reset-scores'){let seed=$('#seed')?.value?.trim()||active?.seed||'', roster=chosen(); if(confirm('Reset the scoreboard for this seed and group?')){resetScores(seed,roster); if(active&&canonical(seed)===active.seed&&JSON.stringify(normalRoster(roster))===JSON.stringify(active.roster)){scores=blankScores(active.roster); persistScores()} draw(false)} return}
 if(action==='view-scores'){modal={type:'scores'}; drawModal(); return}
 if(action==='select-player'){selected=Number(el.dataset.player); draw(); return}
 if(action==='my-god'){openCard(myGod(),true); return}
 if(action==='view'){openCard(el.dataset.god,false); return}
 if(action==='flip-card'){if(modal?.type==='card'){modal.side=modal.side==='front'?'back':'front';drawModal()} return}
 if(action==='close'||action==='close-bg'){modal=null; drawModal(); return}
 if(action==='tick'){toggleTick(Number(el.dataset.player),el.dataset.god); return}
 if(action==='cross'){toggleCross(Number(el.dataset.player),el.dataset.god); return}
 if(action==='recap'){modal={type:'recap'}; drawModal(); return}
 if(action==='reset-notes'){if(confirm('Clear all your deductions for this round?')){board={excluded:{},confirmed:{}}; persistBoard(); draw()} return}
 if(action==='next-round'){if(active.round>=9999){alert('Round limit reached. Change the seed in Setup.'); return} modal={type:'winner'};drawModal();return}
 if(action==='winner-choice'&&modal?.type==='winner'){let winner=Number(el.dataset.winner);if(winner!==0&&!active.roster.includes(winner))return; if(winner){scores[winner]=(scores[winner]||0)+1;persistScores();}const name=winner?playerName(winner):null;startGame(active.seed,active.round+1,active.player,active.roster,active.godCount);if(name)toast(name+' wins the round!');return}
}
document.addEventListener('click',handleClick);
document.addEventListener('submit',e=>{if(e.target.id!=='setupForm') return; e.preventDefault(); let seed=$('#seed').value.trim(), round=Number($('#round').value), player=Number($('#player').value), roster=chosen(), godCount=Number($('#godCount').value); if(!seed){showSetupError('Enter a shared game seed.'); return} if(!validRound(round)){showSetupError('Round must be between 1 and 9999.'); return} if(!validGodCount(godCount)){showSetupError('Choose between 7 and 25 god cards.'); return} if(roster.length<2){showSetupError('Choose at least two players.'); return} if(!roster.includes(player)){showSetupError('Choose your own name from the active players.'); return} startGame(seed,round,player,roster,godCount)});
document.addEventListener('change',e=>{let el=e.target; if(page==='setup') rememberSetupInputs(); if(el.id==='round'){updateSetupRoster();refreshSetupContent();return} if(el.id==='godCount'){setupGodCount=Number(el.value);updateSetupRoster();refreshSetupContent();return} if(el.dataset.roster){let n=Number(el.dataset.roster); if(el.checked) setupSelection.add(n); else {if(setupSelection.size<=2){el.checked=true; showSetupError('At least two people are needed.'); return} setupSelection.delete(n)} updateSetupRoster();refreshSetupContent();return} if(el.dataset.name){names[el.dataset.name]=el.value; putStore(NAMES_KEY,JSON.stringify(names));updateSetupRoster();refreshSetupContent();return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null; drawModal()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&modal?.own){modal=null; drawModal()}});
let incomingConfig=null, incomingError='';
try{if(window.location.hash.startsWith('#ftg=')) incomingConfig=decodeSetupCode(window.location.hash)}
catch(e){incomingError=e.message||'Invalid shared setup link.'}
if(incomingConfig) loadSharedSetup(incomingConfig);
draw(false);
if(incomingError) showSetupError(incomingError);
